(1328, 2, 0, '%s returns the rude gesture to $n.', 12, 7, 0, 0, 0, 0, 1521, 0, 'VMaNGOS'),
(1328, 3, 0, 'What can I do for you?', 12, 7, 0, 0, 0, 0, 1529, 0, 'VMaNGOS'),
(1328, 3, 1, 'What do you fancy, $G sir:miss;?', 12, 7, 0, 0, 0, 0, 1530, 0, 'VMaNGOS'),
(1328, 3, 2, 'Well hello, $n, what can I get you today?', 12, 7, 0, 0, 0, 0, 1531, 0, 'VMaNGOS'),
(1328, 3, 3, 'Been a tough day? A nice ale should loosen those worries right up.', 12, 7, 0, 0, 0, 0, 1532, 0, 'VMaNGOS'),
